INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-chunqiu','燕','["燕","燕国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-1044,"month":1,"confidence":"year"},"end":{"year":-324,"month":12,"confidence":"year"}},{"rank":"王","start":{"year":-323,"month":1,"confidence":"year"},"end":{"year":-222,"month":12,"confidence":"month"}}]}','cn','east_asia',-1044,1,NULL,'year',-222,12,NULL,'month',-12516,-2641,'ochre',NULL,NULL,'周武王封召公奭于燕；战国七雄之一，前222年秦灭燕。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-shi','奭','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名奭，西周初年重臣，燕国始封君。周武王灭商后受封于北燕，留在周王室辅政，由其子就封；成王时位列三公，主治陕以西。后世以《甘棠》传颂其治绩，具体封君起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕召公"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"河南博物院：燕侯旨鼎","url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/clzl/zlhg/dszhzgdwh/debfzmds/article301959f6691644fd9661d4e7ed7e351f.html"}]','召公',NULL,'燕召公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r1','克','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名克，西周早期燕侯，通常认为是召公奭之子。琉璃河出土的克罍、克盉铭文记载周王命克为燕侯，并赐予人口与职官；是早期燕国分封的重要见证。具体在位起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯克"},{"label":"首都博物馆：克罍及分封燕侯铭文","url":"https://www.capitalmuseum.org.cn/collection/30a9844041e24d919ad497143c9db47b"},{"label":"河南博物院：燕侯旨鼎","url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/clzl/zlhg/dszhzgdwh/debfzmds/article301959f6691644fd9661d4e7ed7e351f.html"}]',NULL,NULL,'克','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r10','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥宣侯，在位十三年。春秋前期燕国仍较薄弱，事迹载录甚略，前710–前698年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕宣侯"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','宣侯',NULL,'燕宣侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r11','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥桓侯，在位七年。事迹多见世系记载，政事不见详载，前697–前691年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕桓侯"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','桓侯',NULL,'燕桓侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r12','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕桓侯之后，前690—前658年在位。曾与宋、卫参与拥立王子颓；后来山戎侵燕，齐桓公出兵救援，燕君送齐桓公出境，齐以所至之地赠燕。卒后子襄公继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕庄公"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','庄公',NULL,'燕庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r13','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥襄公，庄公之子。在位近四十年，燕国仍居东偏小国之列，前657–前618年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕襄公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','襄公',NULL,'燕襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r14','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','谥桓，有两段在位：前617–前602年与前372–前362年；或为同名异君，史家有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕桓公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','桓公',NULL,'燕桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r15','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥宣公，在位十四年。春秋中期燕国仍多赖世系记载，前601–前587年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕宣公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','宣公',NULL,'燕宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r16','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥昭公，在位十二年，政治军事事迹载录甚略，年代见于《燕世家》，前586–前574年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕昭公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','昭公',NULL,'燕昭公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r17','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥武公，在位十八年，世系可考而政事少见详载，年代见于《燕世家》，前573–前555年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕武公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','武公',NULL,'燕武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r18','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕前文公，燕武公之后，前554—前549年在位，卒后燕懿公继立。《史记·燕召公世家》记其在位六年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕前文公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','文公',NULL,'燕文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r19','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥懿公，在位仅四年，事迹载录甚略，年代见于《燕世家》，前548–前545年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕懿公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','懿公',NULL,'燕懿公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r2','旨','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名旨，西周早期燕侯，见于燕侯旨鼎等青铜器铭文。通常列为克之后的燕君，关于其为克之弟或克之子的关系，学者有不同解释。具体在位起讫年代失考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯旨"},{"label":"河南博物院：燕侯旨鼎","url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/clzl/zlhg/dszhzgdwh/debfzmds/article301959f6691644fd9661d4e7ed7e351f.html"},{"label":"燕国君主列表及所据考古、世系研究","url":"https://zh.wikipedia.org/wiki/燕国#君主列表"}]',NULL,NULL,'旨','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r20','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','谥惠（春秋），曾出亡齐后复位。在位时与齐、晋多有交往，前544–前536年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕惠公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','惠公',NULL,'燕惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r21','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥悼公，在位六年，事迹载录甚略，年代见于《燕世家》，前535–前529年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕悼公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','悼公',NULL,'燕悼公','[]');
