INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r24','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥简公（春秋），在位十二年，前504–前493年在位；与战国燕简公为不同君主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕简公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','简公',NULL,'燕简公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r25','桓','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','名桓，谥孝公。在位三十七年，战国初期燕国仍偏处东北，事迹载于《燕世家》，前492–前455年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕孝公"}]','孝公',NULL,'燕孝公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r26','戴','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬戴，谥成公。在位十六年，事迹载录甚略，年代见于《燕世家》，前454–前439年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕成公"}]','成公',NULL,'燕成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r27','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥闵公，在位二十四年，事迹载录甚略，年代见于《燕世家》，前438–前415年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕闵公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','闵公',NULL,'燕闵公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r28','载','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','名载，谥简公（战国）。在位四十余年，前414–前373年；后被桓公二世所代，事迹载于《燕世家》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕简公"}]','简公',NULL,'燕简公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r3','舞','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，名舞，西周早期燕侯，出土铜器有“匽侯舞”等铭文，传世文献未载其政事。学者据铭文考订其世次；与其他早期燕侯的关系及具体在位起讫年代仍有未明之处。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯舞"},{"label":"燕国君主列表及所据考古、世系研究","url":"https://zh.wikipedia.org/wiki/燕国#君主列表"}]',NULL,NULL,'舞','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r30','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕后文公，燕桓公之后、燕易王之父，前361—前333年在位。燕国君主世系表将其与春秋时期燕前文公区分；本名失载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕后文公"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','文公',NULL,'燕后文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r31','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥易王，文公之后。在位时燕与齐争，事迹载于战国史料，前332–前321年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕易王"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"《资治通鉴》卷2","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷002"}]','易王',NULL,'燕易王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r32','哙','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬哙，无谥。听信邹子之等，禅位于相子之，引发内乱，齐国田章破燕，哙死，前320–前314年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/哙"}]',NULL,NULL,'哙','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r33','职','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬职，燕王哙庶兄。流落赵国后复国即位；用乐毅、邹衍等，合五国伐齐，占齐七十余城，前312–前279年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕昭王"}]','昭王',NULL,'燕昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r34','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','谥惠（战国）。疑乐毅而召还，乐毅奔赵；后与齐、秦较量，前278–前271年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕惠王"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','惠王',NULL,'燕惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r35','讙','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬讙，谥武成。在位十二年，燕国国力经昭惠之后已不如前，前270–前258年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕武成王"}]','武成王',NULL,'燕武成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r36','遇','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬遇，谥孝王（战国）。在位仅三年，事迹载录甚略，年代见于《燕世家》，前257–前255年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕孝王"}]','孝王',NULL,'燕孝王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r37','喜','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬喜，无谥。秦将王翦、李信攻燕，喜逃亡辽东，后被俘处死，燕亡，前254–前222年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/喜"}]',NULL,NULL,'喜','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r4','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕国西周君主，前864—前827年在位。《史记·燕召公世家》记召公以下九世至惠侯；其在位期间经历周厉王奔彘与共和，周宣王初立时去世，子釐侯继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕惠侯"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/zh-hans/史記/卷014"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','惠侯',NULL,'燕惠侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r5','庄','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','燕惠侯之子，名庄，谥釐侯，前826—前791年在位。其二十一年郑桓公初封于郑；在位三十六年而卒，子顷侯继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕釐侯"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/zh-hans/史記/卷014"}]','釐侯',NULL,'燕釐侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r6','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥顷侯。事迹在《史记·燕世家》及后世追述中甚略，前790–前767年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕顷侯"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','顷侯',NULL,'燕顷侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r7','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥哀侯，在位仅二年。卒后由郑侯继立，事迹载录甚略，前766–前765年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕哀侯"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','哀侯',NULL,'燕哀侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r8','郑','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，称燕郑侯。《史记索隐》指出谥法无“郑”，推测“郑”或为其名；此说存疑。相传在位三十六年，前764–前729年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕郑侯"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]',NULL,NULL,'燕郑侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yan-r9','','yan-chunqiu','[]','姬','匽',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','姬姓，谥穆侯，世系所载君主，政事不见详载，年代见于《燕世家》，前728–前711年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕穆侯"},{"label":"《史记三家注·燕召公世家》","url":"https://ctext.org/wiki.pl?chapter=554855&if=gb&remap=gb"}]','穆侯',NULL,'燕穆侯','[]');
