INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('yan-yi-assumes-kingship','燕易君称王','politics','point','year',NULL,NULL,'采用前323年系年；五国相王的参与及赵是否实际称王应区分，不能将赵武灵王拒绝王号改写为同年正式称王。',-323,12,NULL,-3853,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-323年，燕君在易王十年采用王号。此前齐国乘燕新丧夺取十城，燕通过苏秦交涉收回失地；在诸侯相互承认王号、结交以抗衡大国的背景下，燕与韩相继称王。燕由侯称转入王称，表达与其他诸侯王对等的诉求，不能据此认定获得周王册封。',NULL,NULL,'[{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"《资治通鉴》卷2","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷002"}]');
